SELECT demo_songs.song_title, demo_songs.artist_name, new_artists.genre
FROM demo_songs
JOIN new_artists ON demo_songs.artist_name = new_artists.name;

SELECT demo_songs.song_title, new_artists.city, new_artists.state
FROM demo_songs
JOIN new_artists ON demo_songs.artist_name = new_artists.name;

SELECT demo_songs.song_title, demo_songs.submission_date, new_artists.genre
FROM demo_songs
JOIN new_artists ON demo_songs.artist_name = new_artists.name;
